// Public native noise descriptors and unchanged energy cadence; no logarithmic sine oracle.
package main
import("encoding/csv";"encoding/json";"flag";"fmt";"os";"path/filepath";"strconv")
type noise_energy_job struct{profile,column,input,output string;start,stride int;check_only bool}
func main(){var j noise_energy_job;flag.StringVar(&j.profile,"profile","","N0|N1|N2|N3");flag.StringVar(&j.column,"column","linear","public PCM column");flag.StringVar(&j.output,"output","","fresh output directory");flag.IntVar(&j.start,"start-sample",-1,"actual host-upper+128 native bound");flag.IntVar(&j.stride,"native-stride",1,"native-only input");flag.BoolVar(&j.check_only,"check-only",false,"strict input/geometry only; no numeric scoring");flag.Parse();if flag.NArg()!=1{fmt.Fprintln(os.Stderr,"use -profile N0|N1|N2|N3 -start-sample N -output NEW_DIRECTORY INPUT.csv");os.Exit(2)};j.input=flag.Arg(0);if e:=j.run();e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
func(j *noise_energy_job)run()error{
 if j.profile!="N0"&&j.profile!="N1"&&j.profile!="N2"&&j.profile!="N3"||j.stride!=1||j.start<512||j.start>16384-256{return fmt.Errorf("exact native profile/bounds required")};if e:=fresh_output(j.output);e!=nil{return e};var e error;j.input,e=absolute_path(j.input);if e!=nil{return e};j.output,e=absolute_path(j.output);if e!=nil{return e};raw,e:=os.ReadFile(j.input);if e!=nil{return e};values,e:=strict_public_csv(raw,j.column,16384);if e!=nil{return e};minimum:=4096;if j.profile=="N2"||j.profile=="N3"{minimum=6407};eligible:=len(values)-j.start>=minimum
 if j.check_only{return json.NewEncoder(os.Stdout).Encode(map[string]interface{}{"state":"structural_input_geometry_only_no_numeric_run","input_sha256":public_digest(raw),"horizon_eligible":eligible,"minimum_horizon":minimum})}
 v:=values[j.start:];noise:=score_noise(v);report:=map[string]interface{}{"state":"finite_noise_observations_retained","profile":j.profile,"input":j.input,"input_sha256":public_digest(raw),"column":j.column,"native_stride":1,"first_sample":j.start,"end_exclusive":len(values),"horizon_eligible":eligible,"minimum_horizon":minimum,"stationary_noise_descriptor":noise,"limits":[]string{"No seed/sequence/internal-clock/full-period oracle","Noise AM uses power only; no sine amplitude8170 or TL/dB expectation","Unexpected audio/core states retained; no model-agreement gate"}}
 e=os.Mkdir(j.output,0755);if e!=nil{return e};if j.profile=="N2"||j.profile=="N3"{result:=score_energy(v);report["energy"]=result;report["nominal_period_native_hypothesis"]=32768./31;if len(result.Bounds)==2{report["measured_support_contains_nominal_hypothesis"]=result.Bounds[0]<=32768./31&&32768./31<=result.Bounds[1]};curve:=filepath.Join(j.output,"power.csv");e=write_native_power(curve,v,j.start);if e!=nil{return e};data,e:=os.ReadFile(curve);if e!=nil{return e};report["curve"]=map[string]string{"path":curve,"sha256":public_digest(data)}};data,e:=json.MarshalIndent(report,"","  ");if e!=nil{return e};e=write_exclusive(filepath.Join(j.output,"report.json"),append(data,'\n'));if e!=nil{return e};fmt.Println(string(data));return nil
}
func native_power_curve(v []float64)[]float64{
 power:=make([]float64,len(v)-31);var sum float64;for i,x:=range v{sum+=x*x;if i>=32{sum-=v[i-32]*v[i-32]};if i>=31{power[i-31]=sum/32}}
 return power
}
func write_native_power(path string,v []float64,first int)error{file,e:=os.OpenFile(path,os.O_CREATE|os.O_EXCL|os.O_WRONLY,0600);if e!=nil{return e};w:=csv.NewWriter(file);e=w.Write([]string{"sample_center","native_mean_square_power"});if e!=nil{file.Close();return e};for i,x:=range native_power_curve(v){e=w.Write([]string{strconv.FormatFloat(float64(first+i)+15.5,'g',15,64),strconv.FormatFloat(x,'g',15,64)});if e!=nil{file.Close();return e}};w.Flush();e=w.Error();close_error:=file.Close();if e!=nil{return e};return close_error}
